    "authors": "Nell Minow / ValueEdge Advisors",
    "abstract": "Posted by Nell Minow, ValueEdge Advisors, on Tuesday, July 28, 2026 Editor's Note: Nell Minow is the Vice Chair at ValueEdge Advisors. This post is based on her SEC comment letter. I write in strong opposition to the proposal to reduce reporting to file semiannual reports on the new Form 10-S in lieu of quarterly reports on Form 10-Q. I note that this was prepared entirely by me, without the aid of AI or any LLMs. I agree with many of the thoughtful comments from investors, like the excellent comment from Marcie Frost, CEO of CalPERS, especially this: If the Commission’s objective is to lengthen corporate decision-making horizons, then the more effective and well-targeted lever, as we have urged in prior comment letters, is to discourage the voluntary issuance of forward quarterly earnings guidance, not to dilute the historical financial reporting on which investors depend. (more…)",
