    "title": "The Delaware Supreme Court Issues a 3-2 Split Decision Allowing Post-Demand Evidence to Be Admissible in Section 220 Actions",
    "authors": "",
    "abstract": "Posted by Lauren Rosenello and Tanisha Brown, Skadden, Arps, Slate, Meagher & Flom LLP, on Tuesday, July 28, 2026 Editor's Note: Lauren Rosenello is a Counsel and Tanisha Brown is an Associate at Skadden, Arps, Slate, Meagher & Flom LLP. This post is based on their Skadden memorandum, and is part of the Delaware Law series ; links to other posts in the series are available here . There have been several notable split decisions over the years in the Delaware Supreme Court, but it is a rara avis to see the justices split 3-2 over an issue involving access to books and records. On March 25, 2026, a divided Delaware Supreme Court majority held that in exceptional circumstances, the Court of Chancery may consider post-demand evidence in the Section 220 context when analyzing whether a stockholder had a credible basis to suspect wrongdoing. Justice Gary F. Traynor authored the majority’s opinion, ruling, among other things, that “nothing in [8 Del. C.] Section 220’s text prohibits the consideration of post-demand evidence,” and that a blanket prohibition could result in inefficiencies such as a repetitive process of updated demands and complaints. [1] Chief Justice Collins J. Seitz, Jr. ",
