    "title": "Comment Letter on the SEC’s Proposal to Replace Quarterly Reporting with Semiannual Reporting",
    "authors": "",
    "abstract": "Posted by Donald A. Zakrowski, Eli Lilly and Co., on Saturday, July 18, 2026 Editor's Note: Donald A. Zakrowski is Senior Vice President, Finance, and Chief Accounting Officer at Eli Lilly & Co. This post is based on his SEC comment letter. Eli Lilly and Company (“Lilly”) appreciates the opportunity to submit comments in response to the Securities and Exchange Commission’s (the “Commission”) proposed rule on Semiannual Reporting, released on May 5, 2026. Lilly is engaged in the discovery, development, manufacturing, marketing, and sales of pharmaceutical products worldwide. Founded in 1876 and listed on the New York Stock Exchange for over 70 years, Lilly has a long history of commitment to transparent and timely disclosure to its shareholders and the investing public. We commend the Commission for its thoughtful initiative to modernize the financial reporting landscape for Exchange Act reporting companies. (more…)",
