    "title": "Board Oversight of AI: Why Process Controls May Not Be Enough",
    "authors": "Eva M Erpenbach",
    "abstract": "Companies deploying artificial intelligence have built a recognisable governance apparatus around it. There are usage policies, approval workflows, model inventories, audit trails, risk management functions and requirements for human oversight. Regulatory expectations, from the EU Artificial Intelligence Act to sectoral supervisory guidance, reinforce this architecture and give boards a clearer checklist for responsible deployment. This is necessary work…",
