    "title_zh": "董事会对人工智能的监督：为什么过程控制可能还不够",
    "abstract_zh": "部署人工智能的公司已经围绕它建立了一个公认的治理机构。有使用政策、审批工作流程、模型清单、审计跟踪、风险管理功能和人工监督要求。从欧盟人工智能法案到部门监管指南的监管期望强化了这一架构，并为董事会提供了更清晰的负责任部署清单。这是必要的工作……"
