    "title_zh": "极限学习：从信用延期中推断收入",
    "abstract_zh": "摘要：本文将随机对照试验与行政和调查数据相结合，表明信用额度延期显着增加了总支出和收入预期。通过控制个人收入预期的变化，对信用额度延期的支出反应减弱了约 30%。对于经济上不受限制的消费者来说，预期变化约占限制延期支出反应的三分之二。这些发现与消费者从信贷供应中推断未来收入是一致的。"
