    "title_zh": "流动性监管和银行融资成本",
    "abstract_zh": "我们在流动性监管与银行批发融资成本降低之间建立了因果关系。为了进行识别，我们在双重差分设置中使用银行流动性覆盖率（LCR）的预先确定的变化。精细的工具级数据使我们能够在债权人、工具类型和宏观经济层面仔细控制任何可观察和不可观察的时变因素。我们发现，LCR 敞口较大的银行的批发融资成本下降幅度更大。"
